<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { userDataApi } from '../api/userData'
import { ApiError } from '../api/http'
import { useAuthStore } from '../stores/auth'
import UserPcaScatter from '../charts/UserPcaScatter.vue'
import OfficialCompleteness from '../components/OfficialCompleteness.vue'
import type { UserAnalysis, UserAnalysisReport, UserDataset } from '../types/userData'
const route = useRoute(), router = useRouter(), auth = useAuthStore()
const job = ref<UserAnalysis | null>(null), report = ref<UserAnalysisReport | null>(null), dataset = ref<UserDataset | null>(null)
const error = ref(''), loading = ref(false), tab = ref<'expression' | 'metabolism' | 'files'>('expression')
let timer: number | undefined, revision = 0, stopped = false
const statusLabel = computed(() => ({queued: '排队中', running: '分析中', completed: '已完成', failed: '分析失败'}[job.value?.status ?? 'queued']))
const number = (value: number | undefined) => value === undefined ? '—' : value.toLocaleString(undefined, {maximumFractionDigits: 4})
const fileLabel: Record<string, string> = {'report.json': '完整分析报告', 'gene_summary.csv': '全部基因与分组统计', 'cell_quality.csv': '逐细胞质控', 'official_completeness.json': '官方完整性与缺失基因', 'task_scores.csv': '逐细胞代谢任务评分', 'reaction_scores.csv': '逐细胞反应评分', 'task_group_summary.csv': '代谢任务分组比较', 'gene_identity.json': '基因身份映射'}
async function load() {
  if (timer) window.clearTimeout(timer)
  const id = String(route.params.analysisId), current = ++revision
  loading.value = true; error.value = ''
  try {
    const result = await userDataApi.analysis(id)
    if (stopped || current !== revision) return
    job.value = result
    const source = await userDataApi.dataset(result.dataset_id)
    if (stopped || current !== revision) return
    dataset.value = source
    if (result.status === 'completed') {
      const content = await userDataApi.report(id)
      if (!stopped && current === revision) report.value = content
    } else if (result.status !== 'failed') timer = window.setTimeout(load, 2500)
  } catch (reason) {
    if (stopped || current !== revision) return
    error.value = reason instanceof Error ? reason.message : '分析读取失败'
    if (reason instanceof ApiError && reason.status === 401) {await auth.refresh(); await router.push({path: '/login', query: {next: route.fullPath}})}
  } finally {if (current === revision) loading.value = false}
}
watch(() => route.params.analysisId, () => {job.value = null; report.value = null; dataset.value = null; void load()}, {immediate: true})
onBeforeUnmount(() => {stopped = true; revision++; if (timer) window.clearTimeout(timer)})
</script>
<template>
  <div class="page analysis-page">
    <header class="page-heading"><div><span class="eyebrow">USER DATA ANALYSIS</span><h1>{{ job?.kind === 'metabolism' ? '代谢分析' : '表达探索' }}</h1><p>{{ dataset?.name ?? '正在读取数据集…' }} · {{ statusLabel }}</p></div><div class="btn-row"><RouterLink :to="{path: '/datasets', query: {dataset: job?.dataset_id}}" class="btn">返回我的数据</RouterLink><button class="btn" :disabled="loading" @click="load">刷新状态</button></div></header>
    <div v-if="error" class="notice notice-danger" role="alert">{{ error }}<button class="btn btn-sm" @click="load">重试</button></div>
    <div v-if="job?.status === 'failed'" class="card failure" role="alert"><h2>分析未完成</h2><p>{{ job.error_message }}</p><p class="muted">原始数据仍然保留。检查数据或服务配置后，可回到数据集创建新任务。</p></div>
    <div v-else-if="job && job.status !== 'completed'" class="card progress" role="status"><span class="eyebrow">{{ job.status === 'queued' ? 'WAITING FOR CPU WORKER' : 'ANALYSING EXPRESSION' }}</span><h2>{{ statusLabel }}</h2><p>任务保存在服务器，关闭页面后仍会继续。完成后显示结果。</p><code>{{ job.id }}</code></div>
    <template v-if="report && job">
      <section class="analysis-metrics"><div><strong>{{ number(report.qc.n_cells) }}</strong><span>分析细胞数</span></div><div><strong>{{ number(report.qc.n_genes) }}</strong><span>完整输入基因面板</span></div><div><strong>{{ number(report.qc.median_detected_genes) }}</strong><span>每细胞检出基因中位数</span></div><div><strong>{{ Object.keys(report.qc.groups).length }}</strong><span>{{ report.comparison.group_key ? `分组：${report.comparison.group_key}` : '未分组' }}</span></div></section>
      <nav class="analysis-tabs" aria-label="分析结果"><button :class="{active: tab === 'expression'}" @click="tab = 'expression'">表达与细胞质控</button><button v-if="report.metabolism" :class="{active: tab === 'metabolism'}" @click="tab = 'metabolism'">代谢任务与完整性</button><button :class="{active: tab === 'files'}" @click="tab = 'files'">数据来源与下载</button></nav>
      <template v-if="tab === 'expression'"><div class="result-layout"><section class="card"><span class="eyebrow">EXPRESSION STRUCTURE</span><h2>表达 PCA</h2><p class="muted">按表达方差选择 {{ report.projection.selected_genes.length }} 个基因，展示 {{ report.projection.plotted_cells }} / {{ report.projection.total_cells }} 个真实细胞。坐标来自 log1p(CP10K) 表达矩阵。</p><UserPcaScatter :projection="report.projection" /><div class="group-legend"><span v-for="(count, group) in report.qc.groups" :key="group">{{ group }} · {{ count }} 细胞</span></div></section><aside class="card"><span class="eyebrow">QUALITY & INTERPRETATION</span><h2>质控与解读</h2><dl><dt>零表达细胞</dt><dd>{{ report.qc.zero_expression_cells }}</dd><dt>原始表达单位</dt><dd>{{ report.provenance.metadata.expression_scale }}</dd><dt>参考组</dt><dd>{{ report.comparison.reference_group ?? '未设置' }}</dd><dt>PCA 随机种子</dt><dd>{{ report.projection.seed }}</dd></dl><p>{{ report.comparison.interpretation }}</p><p v-for="warning in report.warnings" :key="warning" class="muted">{{ warning }}</p><a class="btn btn-sm" :href="userDataApi.artifactUrl(job.id, 'cell_quality.csv')">下载逐细胞质控</a></aside></div><section class="card"><div class="section-title"><div><h2>{{ report.comparison.reference_group ? '组间表达差值' : '各组表达均值' }}</h2><p class="muted">展示前 {{ report.genes.length }} 行；完整结果包含全部基因与各分组。均值与差值单位为 log1p(CP10K)。</p></div><a class="btn btn-sm" :href="userDataApi.artifactUrl(job.id, 'gene_summary.csv')">下载完整 CSV</a></div><div class="table-wrap"><table><thead><tr><th>基因</th><th>分组</th><th>细胞数</th><th>平均表达</th><th>检出率</th><th v-if="report.comparison.reference_group">相对参考组差值</th></tr></thead><tbody><tr v-for="(gene, index) in report.genes" :key="index"><td>{{ gene.gene }}</td><td>{{ gene.group }}</td><td>{{ gene.n_cells }}</td><td>{{ number(gene.mean_log1p_cp10k) }}</td><td>{{ (gene.detection_fraction * 100).toFixed(1) }}%</td><td v-if="report.comparison.reference_group" :class="(gene.delta_log1p_cp10k ?? 0) > 0 ? 'up' : 'down'">{{ number(gene.delta_log1p_cp10k) }}</td></tr></tbody></table></div></section></template>
      <template v-else-if="tab === 'metabolism' && report.metabolism"><section class="card"><span class="eyebrow">SCCELLFIE / MEASURED EXPRESSION</span><h2>完整上传面板的代谢分析</h2><p class="muted">{{ report.metabolism.interpretation }}</p><p>本面板可评分 {{ report.metabolism.n_tasks }} / {{ report.metabolism.n_tasks_database }} 项任务、{{ report.metabolism.n_reactions }} / {{ report.metabolism.n_reactions_database }} 个反应；冻结数据库版本 {{ report.metabolism.database_version }}。</p><p class="muted">{{ report.metabolism.score_scope }}</p><details v-if="report.metabolism.unscored_tasks.length"><summary>查看未返回评分的 {{ report.metabolism.unscored_tasks.length }} 项任务</summary><p v-for="task in report.metabolism.unscored_tasks" :key="task" class="muted">{{ task }}</p></details><OfficialCompleteness :analysis-id="job.id" :available="true" /><p class="muted">官方完整性衡量本数据集的基因可用范围。分母来自完整冻结数据库；完整覆盖不代表实测通量或模型准确率。</p><a class="btn" :href="userDataApi.artifactUrl(job.id, 'official_completeness.json')">下载完整性与缺失基因 JSON</a></section><section class="card"><div class="section-title"><div><h2>代谢任务分组评分</h2><p class="muted">展示前 {{ report.metabolism.tasks.length }} 行。{{ report.comparison.reference_group ? `差值相对于 ${report.comparison.reference_group}` : '未设置参考组，展示各组均值' }}。</p></div><a class="btn btn-sm" :href="userDataApi.artifactUrl(job.id, 'task_group_summary.csv')">下载完整 CSV</a></div><div class="table-wrap"><table><thead><tr><th>任务</th><th>分组</th><th>平均评分</th><th v-if="report.comparison.reference_group">相对参考组差值</th></tr></thead><tbody><tr v-for="(task, index) in report.metabolism.tasks" :key="index"><td>{{ task.id }}</td><td>{{ task.group }}</td><td>{{ number(task.mean_score) }}</td><td v-if="report.comparison.reference_group" :class="(task.delta ?? 0) > 0 ? 'up' : 'down'">{{ number(task.delta) }}</td></tr></tbody></table></div></section></template>
      <section v-else-if="tab === 'files'" class="card"><span class="eyebrow">PROVENANCE & EXPORT</span><h2>数据来源与结果文件</h2><dl class="provenance"><dt>分析编号</dt><dd class="mono">{{ job.id }}</dd><dt>数据集版本</dt><dd class="mono">{{ report.dataset_id }}</dd><dt>源文件 SHA-256</dt><dd class="mono">{{ report.provenance.source_sha256 }}</dd><dt>分析实现版本</dt><dd>{{ report.provenance.analysis_version }}</dd></dl><p class="muted">下载时检查所属账号与文件 SHA-256。文件仅对你的账号开放。</p><div class="artifact-list"><a v-for="(artifact, filename) in job.artifacts" :key="filename" :href="userDataApi.artifactUrl(job.id, String(filename))"><span><strong>{{ fileLabel[filename] ?? filename }}</strong><small>{{ filename }} · {{ (artifact.size_bytes / 1024).toFixed(1) }} KB</small><code>{{ artifact.sha256 }}</code></span><span>下载 ↓</span></a></div></section>
    </template>
  </div>
</template>
<style scoped>
.analysis-page h2{font-size:20px;font-weight:500;margin:8px 0 12px}.muted{color:var(--muted);font-size:12px;line-height:1.9}.analysis-metrics{display:grid;grid-template-columns:repeat(4,1fr);background:var(--card);border:1px solid var(--border);margin-bottom:24px}.analysis-metrics>div{padding:24px;border-right:1px solid var(--border)}.analysis-metrics>div:last-child{border:0}.analysis-metrics strong{display:block;font:32px Georgia,serif;margin-bottom:8px}.analysis-metrics span{font-size:11px;color:var(--muted)}.analysis-tabs{display:flex;gap:28px;margin-bottom:24px;border-bottom:1px solid var(--border);overflow-x:auto}.analysis-tabs button{background:transparent;border:0;border-bottom:2px solid transparent;padding:14px 0;font:inherit;font-size:13px;color:var(--muted);white-space:nowrap;cursor:pointer}.analysis-tabs button.active{color:var(--primary);border-bottom-color:var(--primary)}.result-layout{display:grid;grid-template-columns:minmax(0,2fr) minmax(220px,1fr);gap:24px;margin-bottom:24px}.result-layout>.card+.card{margin-top:0}.group-legend{display:flex;gap:10px;flex-wrap:wrap}.group-legend span{font-size:10px;background:var(--primary-weak);padding:5px 8px;color:var(--primary)}dl{font-size:12px}dt{color:var(--muted);margin-top:16px}dd{margin:5px 0;overflow-wrap:anywhere}aside p{font-size:12px;line-height:1.9}.section-title{display:flex;align-items:center;justify-content:space-between;gap:14px}.table-wrap{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:12px;text-align:left}th{font-size:11px;font-weight:500;color:var(--muted);background:#edf1ec;white-space:nowrap}td,th{padding:12px;border-bottom:1px solid var(--border)}.up{color:#a65c39}.down{color:var(--primary)}.progress,.failure{padding:45px}.progress p,.failure p{color:var(--muted)}.analysis-page>.notice{margin-bottom:20px}.provenance{display:grid;grid-template-columns:170px 1fr;gap:12px}.provenance dt,.provenance dd{margin:0}.artifact-list>a{display:flex;align-items:center;justify-content:space-between;gap:20px;border-top:1px solid var(--border);padding:18px 0;font-size:12px}.artifact-list strong{font-weight:500}.artifact-list small,.artifact-list code{display:block;color:var(--muted);font-size:10px;margin-top:5px;overflow-wrap:anywhere}.completeness-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin:28px 0}.completeness-grid>div{border-left:2px solid var(--border-strong);padding-left:14px}.completeness-grid code{display:block;font-size:10px;overflow-wrap:anywhere;color:var(--muted)}.completeness-grid strong{display:block;font:24px Georgia,serif;margin-top:8px}@media(max-width:850px){.result-layout{grid-template-columns:1fr}.analysis-metrics{grid-template-columns:1fr 1fr}.analysis-metrics>div{border-bottom:1px solid var(--border)}.completeness-grid{grid-template-columns:1fr 1fr}}@media(max-width:550px){.provenance{grid-template-columns:1fr;gap:6px}.provenance dd{margin-bottom:12px}.analysis-metrics>div{padding:18px}.analysis-metrics strong{font-size:26px}.section-title{display:block}.section-title>.btn{margin-bottom:16px}.artifact-list>a{align-items:start}.artifact-list>a>span:first-child{min-width:0}}
</style>
